<script>
   /*************************************************************/
   /* Root component for the application                        */
   /*************************************************************/

   import { date2str } from '@mdatools-apps/shared/utils';
   import { checkPrepModel, checkPrepChain } from '@mdatools-apps/shared/methods/prep.js';

   import CreateAppContainer from './tab_create/AppContainer.svelte';
   import ApplyAppContainer from './tab_apply/AppContainer.svelte';
   import App from '@mdatools-apps/shared/components/MainApp.svelte';
   import WASM from '@mdatools-apps/wasm/prep_wasm.js';


   /* callback to check validity of JSON with session */
   function checkSession(s) {
      const keys1 = Object.keys(s);
      if (!['date', 'tab', 'create', 'apply'].every(v => keys1.includes(v))) return false;

      // the trim bounds are read by no tab of this build - the create tab keeps its own and the
      // apply tab hands the plots -1 - but the keys stay required here and seeded below: a session
      // stored without them would be refused by the previous build's check
      const keys2 = Object.keys(s.create);
      if (!['rawdata', 'prepdata', 'prepmodel', 'prepobj', 'prepmeta', 'left', 'right']
         .every(v => keys2.includes(v))) return false;

      const keys3 = Object.keys(s.apply);
      if (!['rawdata', 'prepdata', 'model', 'left', 'right'].every(v => keys3.includes(v))) {
         return false;
      }

      // the keys above are required and not their values, with two exceptions. the chain's
      // entries are read by the creator and its widgets as soon as the create tab mounts, where
      // no catch reaches, so each has to be a known method with its parameters; 'prepmeta' is
      // not checked: it is 0 from 'initSession' until the creator mounts and writes its
      // eight-slot array back, and nothing reads it before then. a stored model is rendered by
      // the info panel as soon as the apply tab mounts, so it has to pass the checks a model
      // file passes; 0 and null are no model
      try { checkPrepChain(s.create.prepobj); } catch { return false; }
      if (s.apply.model) {
         try { checkPrepModel(s.apply.model); } catch { return false; }
      }

      // fields an earlier build stored and this one does not read: the short sets are previews
      // cut from the data in the tabs, 'varind' was seeded here and read nowhere. stripped here,
      // the one place both restore paths pass, or a session from that build would carry them in
      // every backup
      delete s.create.rawdataShort;
      delete s.create.prepdataShort;
      delete s.create.varind;
      delete s.apply.rawdataShort;
      delete s.apply.prepdataShort;
      delete s.apply.varind;
      return true;
   }

   /* callback to initialize new session */
   function initSession() {
      return {
         date: date2str(new Date()),
         tab: 0,
         create: {
            rawdata : 0,
            prepdata: 0,
            prepmodel: 0,
            prepobj: [],
            prepmeta: 0,
            left: 0,
            right: 0
         },
         apply: {
            rawdata : 0,
            prepdata: 0,
            model: 0,
            left: 0,
            right: 0
         }
      }
   }

   // app containers
   const tabs = [
      {name: 'Create', label: 'create', component: CreateAppContainer},
      {name: 'Apply', label: 'apply', component: ApplyAppContainer},
   ]


</script>

<App
   appID="prep"
   appTitle="Preprocessing"
   appShortTitle="Preprocessing"
   appSlogan="Make your data great again"
   {WASM}
   {tabs}
   {initSession}
   {checkSession}
>

   {#snippet footer()}
      <p>Current release: <span>1.3.1</span>
      Feedback: <a class="paper-link" href="mailto:help@mda.tools?subject=Preprocessing app">help@mda.tools</a>
      | <a class="paper-link" href="/prep/references.pdf" download>references</a>
      | <a href="https://www.youtube.com/playlist?list=PLep7KM9cEyFmesy9tzG9OzOcSCFigU5hh">video lessons</a>
      </p>
   {/snippet}

   {#snippet info()}
   <h2>Data preprocessing</h2>
   <p>
      Interactive web-application for data preprocessing. Most of the methods it contains are
      applicable for different kinds of spectra. The selected chain of methods and their parameters can be saved as preprocessing model and be applied later to another dataset or incorporated to other methods (PCA, PLS, etc.).
   </p>
   <h3>v. 1.3.1</h3>
   <p class="release-info">released 01/10/2026</p>
   <ul>
      <li>New higher-contrast theme for the control elements.</li>
      <li>Improved accessibility of the controls.</li>
      <li>Small bug fixes and improvements.</li>
   </ul>
   {/snippet}
</App>

